--[=[
    @class IPlayerHostedAsyncService
    异步加载的玩家托管服务接口
    如果构造函数本身是异步加载的, 则需要注册为本服务
]=]

export type IPlayerHostedAsyncService = {
    --- 启动服务
    Start: (self: IPlayerHostedAsyncService) -> (),

    --- 停止服务
    Stop: (self: IPlayerHostedAsyncService) -> (),

    --- 销毁服务
    Dispose: (self: IPlayerHostedAsyncService) -> ()
}

return {}
